import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import '../../shared/ui.dart';

class ReferralScreen extends StatefulWidget { const ReferralScreen({super.key}); @override State<ReferralScreen> createState()=>_ReferralScreenState(); }
class _ReferralScreenState extends State<ReferralScreen>{List<dynamic> referrals=[];bool loading=true;String? error;@override void initState(){super.initState();load();}
 Future<void> load()async{try{final r=await ApiClient.instance.get('/api/v1/referrals');setState(()=>referrals=List.from(r['items']??[]));error=null;}catch(e){error=e.toString();}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> change(String id,String status)async{try{await ApiClient.instance.post('/api/v1/referrals/$id/transition',{'status':status,'note':'Updated from Flutter application'});if(mounted)showMessage(context,'Referral updated to $status');await load();}catch(e){if(mounted)showMessage(context,e.toString(),error:true);}}
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Expanded(child:P360Header('Referral coordination',subtitle:'Track referrals through receiving-facility handover')),IconButton.filled(onPressed:()=>showDialog(context:context,builder:(_)=>_CreateReferralDialog(onCreated:load)),icon:const Icon(Icons.add))])),Expanded(child:loading?const LoadingView():error!=null?Center(child:Text(error!)):referrals.isEmpty?const Center(child:Text('No referrals available.')):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:referrals.length,itemBuilder:(context,i){final r=referrals[i];final status=(r['status']??'generated').toString();return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('Referral ${r['id'].toString().substring(0,8)}',style:const TextStyle(fontWeight:FontWeight.w800)),StatusPill(status,color:status=='completed'?AppColors.success:AppColors.warning)]),const SizedBox(height:8),Text(r['reason']??'No reason recorded'),const SizedBox(height:10),Wrap(spacing:8,children:[if(status=='generated')OutlinedButton(onPressed:()=>change(r['id'],'sent'),child:const Text('Send')),if(status=='sent')OutlinedButton(onPressed:()=>change(r['id'],'acknowledged'),child:const Text('Acknowledge')),if(status=='acknowledged')OutlinedButton(onPressed:()=>change(r['id'],'departed'),child:const Text('Mark departed')),if(status=='departed')OutlinedButton(onPressed:()=>change(r['id'],'arrived'),child:const Text('Mark arrived')),if(status=='arrived')OutlinedButton(onPressed:()=>change(r['id'],'assessed'),child:const Text('Mark assessed')),if(status=='assessed')FilledButton(onPressed:()=>change(r['id'],'completed'),child:const Text('Complete'))])])));}))) ]);}


class _CreateReferralDialog extends StatefulWidget { final Future<void> Function() onCreated; const _CreateReferralDialog({required this.onCreated}); @override State<_CreateReferralDialog> createState()=>_CreateReferralDialogState(); }
class _CreateReferralDialogState extends State<_CreateReferralDialog>{final reason=TextEditingController();List<dynamic> patients=[];String? patientId;bool loading=true,saving=false;
 @override void initState(){super.initState();ApiClient.instance.get('/api/v1/patients?limit=100').then((r){if(mounted)setState(()=>patients=List.from(r['items']??[]));}).catchError((e){if(mounted)showMessage(context,e.toString(),error:true);}).whenComplete(()=>setState(()=>loading=false));}
 Future<void> create()async{if(patientId==null||reason.text.trim().length<3){showMessage(context,'Select a patient and enter a referral reason.',error:true);return;}setState(()=>saving=true);try{await ApiClient.instance.post('/api/v1/referrals',{'patient_id':patientId,'reason':reason.text.trim(),'clinical_summary':{'source':'flutter_app'}});if(mounted){Navigator.pop(context);showMessage(context,'Referral created.');await widget.onCreated();}}catch(e){if(mounted)showMessage(context,e.toString(),error:true);}finally{if(mounted)setState(()=>saving=false);}}
 @override Widget build(BuildContext context)=>AlertDialog(title:const Text('Create referral'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[if(loading)const LinearProgressIndicator(),DropdownButtonFormField<String>(value:patientId,decoration:const InputDecoration(labelText:'Patient'),items:patients.map((p)=>DropdownMenuItem<String>(value:p['id'].toString(),child:Text(p['full_name']??'Patient'))).toList(),onChanged:(v)=>setState(()=>patientId=v)),const SizedBox(height:12),TextField(controller:reason,maxLines:4,decoration:const InputDecoration(labelText:'Reason for referral'))])),actions:[TextButton(onPressed:saving?null:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:saving?null:create,child:saving?const SizedBox(height:18,width:18,child:CircularProgressIndicator(strokeWidth:2)):const Text('Create'))]);}
